import{_ as a,c as e,o as t,ag as n}from"./chunks/framework.DQvKz0xt.js";const u=JSON.parse('{"title":"N轴切片 (N-Slicing) - Rive 编辑器","description":"布局 (Layouts) N轴切片 (N-Slicing) 是一种技术，允许你将位图或矢量设计划分为多个区域，使其在某些方向上可以拉伸或重复，而其他部分保持固定尺寸。这对于创建可伸缩的 UI 组件（如按钮、面板、对话框框架）至关重要。","frontmatter":{"title":"N轴切片 (N-Slicing) - Rive 编辑器","description":"布局 (Layouts) N轴切片 (N-Slicing) 是一种技术，允许你将位图或矢量设计划分为多个区域，使其在某些方向上可以拉伸或重复，而其他部分保持固定尺寸。这对于创建可伸缩的 UI 组件（如按钮、面板、对话框框架）至关重要。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 布局, N轴切片"}]]},"headers":[],"relativePath":"editor/layouts/n-slicing.md","filePath":"editor/layouts/n-slicing.md","lastUpdated":1774838907000}'),l={name:"editor/layouts/n-slicing.md"};function r(o,i,s,c,h,g){return t(),e("div",null,[...i[0]||(i[0]=[n('<p>布局 (Layouts)</p><h1 id="n轴切片-n-slicing" tabindex="-1">N轴切片 (N-Slicing) <a class="header-anchor" href="#n轴切片-n-slicing" aria-label="Permalink to &quot;N轴切片 (N-Slicing)&quot;">​</a></h1><h2 id="​-什么是-n轴切片" tabindex="-1"><a href="#what-is-n-slicing">​</a> 什么是 N轴切片？ <a class="header-anchor" href="#​-什么是-n轴切片" aria-label="Permalink to &quot;[​](#what-is-n-slicing) 什么是 N轴切片？&quot;">​</a></h2><p>N轴切片 (N-Slicing) 是一种技术，允许你将位图或矢量设计划分为多个区域，使其在某些方向上可以拉伸或重复，而其他部分保持固定尺寸。这对于创建可伸缩的 UI 组件（如按钮、面板、对话框框架）至关重要。</p><h3 id="常见切片类型" tabindex="-1">常见切片类型 <a class="header-anchor" href="#常见切片类型" aria-label="Permalink to &quot;常见切片类型&quot;">​</a></h3><ul><li><strong>1-Slice</strong>：单一方向的拉伸。</li><li><strong>3-Slice</strong>：水平方向分为左、中、右三段（左右固定，中间拉伸）。</li><li><strong>9-Slice</strong>：水平和垂直方向都分割，形成 9 个区域（四角固定，边缘拉伸，中心可填充）。</li></ul><h2 id="​-为什么使用-n轴切片" tabindex="-1"><a href="#why-use-n-slicing">​</a> 为什么使用 N轴切片？ <a class="header-anchor" href="#​-为什么使用-n轴切片" aria-label="Permalink to &quot;[​](#why-use-n-slicing) 为什么使用 N轴切片？&quot;">​</a></h2><p>如果不使用切片，当你缩放一个带有圆角的按钮时，圆角会被拉伸变形。通过 N-Slice，你可以确保：</p><ul><li><strong>圆角保持固定</strong>半径。</li><li><strong>边框粗细不变</strong>。</li><li><strong>只有中间区域</strong>被拉伸或平铺。</li></ul><h2 id="​-设置-n轴切片" tabindex="-1"><a href="#setting-up-n-slicing">​</a> 设置 N轴切片 <a class="header-anchor" href="#​-设置-n轴切片" aria-label="Permalink to &quot;[​](#setting-up-n-slicing) 设置 N轴切片&quot;">​</a></h2><ol><li>选中目标对象（一个形状或图片）。</li><li>在检查器 (Inspector) 中找到 <strong>N-Slice</strong> 选项。</li><li>定义切片的边界（上下左右的像素值）。</li><li>选择填充模式：<strong>拉伸 (Stretch)</strong> 或 <strong>平铺 (Tile)</strong>。</li></ol><h2 id="​-矢量图的-n轴切片" tabindex="-1"><a href="#n-slicing-with-vectors">​</a> 矢量图的 N轴切片 <a class="header-anchor" href="#​-矢量图的-n轴切片" aria-label="Permalink to &quot;[​](#n-slicing-with-vectors) 矢量图的 N轴切片&quot;">​</a></h2><p>Rive 不仅支持位图的 N-Slice，还支持矢量资产的切片。这意味着你可以创建保持锐利度的、完全可缩放的 UI 框架——无论在任何分辨率下都不会模糊。</p><h2 id="​-常见应用场景" tabindex="-1"><a href="#common-use-cases">​</a> 常见应用场景 <a class="header-anchor" href="#​-常见应用场景" aria-label="Permalink to &quot;[​](#common-use-cases) 常见应用场景&quot;">​</a></h2><ul><li><strong>按钮</strong>：固定圆角，拉伸中间以适应文本长度。</li><li><strong>对话框/弹窗</strong>：固定边框装饰，扩展内容区域。</li><li><strong>进度条</strong>：两端固定，中间填充。</li><li><strong>游戏 UI 面板</strong>：保持装饰性边角，适应各种尺寸。</li></ul><p><a href="/docs/editor/layouts/overview">布局概览 (Overview)</a><a href="/docs/editor/layouts/layout-parameters">布局参数 (Parameters)</a></p>',16)])])}const N=a(l,[["render",r]]);export{u as __pageData,N as default};
